/**
 * Looks labels up by id across every organization. Only for callers that must
 * tell "belongs to another workspace" apart from "does not exist"; the caller
 * is responsible for checking each row with `assertRowsInScope`.
 */
export async function findLabelsAnyOrg(
  labelIds: readonly LabelId[],
): Promise<readonly IssueLabel[]> {
  if (labelIds.length === 0) return [];

