/**
 * A parent must be a live issue of the same project. A parent that lives in
 * another workspace is a cross-tenant reference and is refused as such; every
 * other unusable parent is reported as not found.
 */
async function requireParentIssue(
  actor: Actor,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<void> {
  const parent = requireFound(
    await issueRepo.findIssueAnyOrg(parentId),
    "Issue",
    parentId,
  );
  assertOrgScope(actor, parent.orgId);

  if (parent.projectId !== projectId || !isLive(parent)) {
    throw new NotFoundError("Issue", parentId);
  }
}

/**
 * Every label on an issue must be one of this workspace's own labels. Labels
 * from another workspace are a cross-tenant reference; unknown ids (including
 * stale ones from a picker) are not found.
 */
async function requireLabels(
  actor: Actor,
  labelIds: readonly LabelId[],
): Promise<void> {
  if (labelIds.length === 0) return;

  const found = await labelRepo.findLabelsAnyOrg(labelIds);
  assertRowsInScope(actor, found);

  const known = new Set(found.map((label) => label.id));
  for (const labelId of labelIds) {
    if (!known.has(labelId)) throw new NotFoundError("Label", labelId);
  }
}

