function isPastEditWindow(comment: Comment): boolean {
  const posted = new Date(comment.createdAt).getTime();
  return Date.now() - posted > EDIT_WINDOW_MS;
}

/**
 * A reply must target a live, top-level comment on this same issue. A comment
 * from another workspace is a cross-tenant reference and is refused as such;
 * every other unusable target (other issue, deleted, or already a reply) is
 * reported as not found.
 */
async function requireReplyTarget(
  actor: Actor,
  issue: Issue,
  parentId: CommentId,
): Promise<void> {
  const parent = requireFound(
    await commentRepo.findCommentAnyOrg(parentId),
    "Comment",
    parentId,
  );
  assertOrgScope(actor, parent.orgId);

  if (
    parent.issueId !== issue.id ||
    parent.parentId !== null ||
    !isLive(parent)
  ) {
    throw new NotFoundError("Comment", parentId);
  }
}

/**
 * Union of the ids the client supplied (composer or optimistic UI) and the
 * ones parsed out of the body server-side, restricted to the org's current
 * active members. Anyone else is dropped silently: they are never stored,
 * never put on the event, and so never notified.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await listActiveMembers(orgId);
  const currentIds = new Set(members.map((member) => member.userId));

  const resolved = resolveMentions(body, members);
  const supplied = clientProvided.filter((userId) => currentIds.has(userId));

  return [...new Set([...resolved, ...supplied])];
}

/** Walks every page of active members, so no member is missed by the lookup. */
async function listActiveMembers(
  orgId: OrgId,
): Promise<readonly MemberWithUser[]> {
  const all: MemberWithUser[] = [];
  let cursor: string | null = null;

  do {
    const page = await memberRepo.listMembers({
      orgId,
      status: "active",
      limit: MENTION_LOOKUP_LIMIT,
      cursor,
    });
    all.push(...page.items);
    cursor = page.nextCursor;
  } while (cursor !== null);

  return all;
}

